 export type CanvasState =
   | { kind: "loading"; data: CanvasData | null }
   | { kind: "ready"; data: CanvasData }
   | { kind: "empty"; data: CanvasData }
   | { kind: "error"; error: StudioError; data: CanvasData | null };

