} from "../api/studioApi";
import type { RawSseEvent } from "../api/sse";
import { applyToolEvent, type RunStep } from "../lib/run";
import { newTurnId } from "../lib/thread";
import type {
  AddConnectorPayload,
  ChatAttachmentPayload,
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  CanvasState,
  ChatMessage,
  ChatPart,
  ConnectorListItem,
  ConnectorPreset,
  Observation,
  StudioBrief,
  StudioConfig,
  StudioError,
