const applyToolEvent = (
  name: string,
  status: ToolStatus,
  preview?: string,
  id?: string,
) => {
  const open = openTool(name);
  if (status === "running") {
    if (open) {
      return;
    }
    toolSeq += 1;
    parts = [
      ...parts,
      { kind: "tool", id: id ?? `tool-${toolSeq}`, name, status },
    ];
    return;
  }
  if (open) {
    const next = {
      ...open,
      status,
      ...(preview ? { preview } : {}),
      // A result means the gate was answered; the question is spent.
      approval: undefined,
    };
    parts = [...parts.filter((part) => part !== open), next];
    return;
  }
  toolSeq += 1;
  parts = [
    ...parts,
    {
      kind: "tool",
      id: id ?? `tool-${toolSeq}`,
      name,
      status,
      ...(preview ? { preview } : {}),
    },
  ];
};

