          kind: "source",
          id: String(event.data.id ?? `src-${parts.length}`),
          title: String(event.data.title ?? ""),
          mediaType: String(event.data.mediaType ?? "application/json"),
          ...(event.data.filename ? { filename: String(event.data.filename) } : {}),
        },
      ];
      publish();
